  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))

const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHex = (c) => c !== undefined && /^[0-9A-Fa-f]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isLetter(c) || isDigit(c) || c === '_'

export function scan(source) {
  const s = Array.from(source)
  const n = s.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  // Advance over s[i], updating position.
  const adv = () => {
    const c = s[i++]
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = Math.floor((col - 1) / 4) * 4 + 5
    } else col++
    return c
  }
  const advTo = (end) => {
    while (i < end) adv()
  }

  // Consume a run of digits (per predicate) with single underscores between digits; returns end index.
  const run = (j, pred) => {
    if (!pred(s[j])) return j
    j++
    for (;;) {
      if (pred(s[j])) j++
      else if (s[j] === '_' && pred(s[j + 1])) j += 2
      else return j
    }
  }

  while (i < n) {
    const c = s[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      adv()
      continue
    }
    if (c === '/' && s[i + 1] === '/') {
      while (i < n && s[i] !== '\n') adv()
      continue
    }
    if (c === '/' && s[i + 1] === '*') {
      const sl = line
      const sc = col
      adv()
      adv()
      let depth = 1
      while (i < n && depth > 0) {
        if (s[i] === '/' && s[i + 1] === '*') {
          adv()
          adv()
          depth++
        } else if (s[i] === '*' && s[i + 1] === '/') {
          adv()
          adv()
          depth--
        } else adv()
      }
      if (depth > 0) throw new ScanError(sl, sc, 'unterminated block comment')
      continue
    }
    const tl = line
    const tc = col
    if (isIdStart(c)) {
      if (c === 'r' && s[i + 1] === '"') {
        adv()
        adv()
        let value = ''
        while (i < n && s[i] !== '"') value += adv()
        if (i >= n) throw new ScanError(tl, tc, 'unterminated string')
        adv()
        tokens.push({ line: tl, col: tc, kind: 'rawstring', value })
        continue
      }
      let j = i
      while (isIdPart(s[j])) j++
      const text = s.slice(i, j).join('')
      advTo(j)
      tokens.push({ line: tl, col: tc, kind: KEYWORDS.has(text) ? 'keyword' : 'ident', text })
      continue
    }
    if (isDigit(c)) {
      let j = i
      let ok = true
      const p = s[i + 1]
      const pref = c === '0' && p !== undefined ? p.toLowerCase() : ''
      if (pref === 'x' || pref === 'b' || pref === 'o') {
        const pred = pref === 'x' ? isHex : pref === 'b' ? isBin : isOct
        j = run(i + 2, pred)
        if (j === i + 2) ok = false
      } else {
        j = run(i, isDigit)
        if (s[j] === '.' && isDigit(s[j + 1])) j = run(j + 1, isDigit)
        if (s[j] === 'e' || s[j] === 'E') {
          let k = j + 1
          if (s[k] === '+' || s[k] === '-') k++
          if (isDigit(s[k])) j = run(k, isDigit)
        }
      }
      if (!ok || isIdPart(s[j])) {
        while (isIdPart(s[j])) j++
        throw new ScanError(tl, tc, `invalid number ${s.slice(i, j).join('')}`)
      }
      const text = s.slice(i, j).join('')
      advTo(j)
      tokens.push({ line: tl, col: tc, kind: 'number', text })
      continue
    }
    if (c === '"') {
      adv()
      let value = ''
      for (;;) {
        if (i >= n) throw new ScanError(tl, tc, 'unterminated string')
        const d = s[i]
        if (d === '"') {
          adv()
          break
        }
        if (d === '\n') throw new ScanError(line, col, 'newline in string')
        if (d !== '\\') {
          value += adv()
          continue
        }
        const el = line
        const ec = col
        adv()
        if (i >= n) throw new ScanError(tl, tc, 'unterminated string')
        const e = s[i]
        const bad = () => new ScanError(el, ec, `invalid escape \\${e}`)
        if (e === 'n') value += '\n'
        else if (e === 't') value += '\t'
        else if (e === 'r') value += '\r'
        else if (e === '\\') value += '\\'
        else if (e === '"') value += '"'
        else if (e === '0') value += '\0'
        else if (e === 'x') {
          if (!isHex(s[i + 1]) || !isHex(s[i + 2])) throw bad()
          value += String.fromCodePoint(parseInt(s[i + 1] + s[i + 2], 16))
          adv()
          adv()
        } else if (e === 'u') {
          if (s[i + 1] !== '{') throw bad()
          let j = i + 2
          let h = ''
          while (isHex(s[j])) h += s[j++]
          if (h === '' || s[j] !== '}') throw bad()
          const cp = parseInt(h, 16)
          if (cp > 0x10ffff) throw bad()
          value += String.fromCodePoint(cp)
          advTo(j)
        } else throw bad()
        adv()
      }
      tokens.push({ line: tl, col: tc, kind: 'string', value })
      continue
    }
    const two = c + (s[i + 1] ?? '')
    if (PUNCT2.has(two)) {
      adv()
      adv()
      tokens.push({ line: tl, col: tc, kind: 'punct', text: two })
      continue
    }
    if (PUNCT1.has(c)) {
      adv()
      tokens.push({ line: tl, col: tc, kind: 'punct', text: c })
      continue
    }
    throw new ScanError(tl, tc, `unexpected character ${c}`)
  }
  return tokens
}
"}

