      continue
    }
    if (c === '/' && s[i + 1] === '*') {
      const sl = line
      const sc = col
      adv()
      adv()
      let depth = 1
      while (i < n && depth > 0) {
        if (s[i] === '/' && s[i + 1] === '*') {
          adv()
          adv()
          depth++
        } else if (s[i] === '*' && s[i + 1] === '/') {
          adv()
          adv()
          depth--
        } else adv()
      }
      if (depth > 0) throw new ScanError(sl, sc, 'unterminated block comment')
      continue
    }
    const tl = line
    const tc = col
    if (isIdStart(c)) {
      if (c === 'r' && s[i + 1] === '"') {
        adv()
        adv()
        let value = ''
